"""Remove report files generated by the cleanup-cds workflow."""

from __future__ import annotations

import argparse
from pathlib import Path


GENERATED_FILES = (
    "01-inventory.csv",
    "02-mapping.csv",
    "03-missing-track-report.csv",
    "04-album-summary.csv",
    "05-playlist.m3u",
    "06-track-analysis.csv",
)

XLSX_FILES = (
    "01-inventory.xlsx",
    "03-missing-track-report.xlsx",
    "04-album-summary.xlsx",
)


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Remove known generated report files from cleanup-cds."
    )
    parser.add_argument(
        "--apply",
        action="store_true",
        help="Delete the generated files. Without this flag, only list what would be removed.",
    )
    parser.add_argument(
        "--include-xlsx",
        action="store_true",
        help="Include generated .xlsx files in the reset. They are excluded by default.",
    )
    return parser.parse_args()


def main() -> int:
    args = parse_args()
    cleanup_dir = Path(__file__).resolve().parent
    generated_files = GENERATED_FILES + (XLSX_FILES if args.include_xlsx else ())
    existing_files = [
        cleanup_dir / filename
        for filename in generated_files
        if (cleanup_dir / filename).is_file()
    ]

    if not existing_files:
        print("No generated files found.")
        return 0

    action = "DELETE" if args.apply else "WOULD DELETE"
    for path in existing_files:
        print(f"{action}: {path.name}")

    if args.apply:
        for path in existing_files:
            path.unlink()
        print(f"Removed: {len(existing_files)}")
    else:
        print(f"Found: {len(existing_files)}")
        print("Dry run only. Re-run with --apply to remove these files.")

    return 0


if __name__ == "__main__":
    raise SystemExit(main())
